import React from 'react';

interface DoDontProps {
    element: any;
    text: string;
    state: string;
}

export const DoDont = ({ element, text, state }: DoDontProps) => {
    let message:string = '';
    let boxStyle:React.CSSProperties = {};
    let textStyle:React.CSSProperties = {};

    const styles: { [key: string]: React.CSSProperties } = {
        Dont: { border: '1px solid red', backgroundColor: '#ffe6e6' },
        Do: { border: '1px solid green', backgroundColor: '#e6ffe6' }
    };

    boxStyle = { ...styles[state], padding: '10px', borderRadius: '10px', marginTop: '4px' };
    textStyle = { backgroundColor: state === 'Do' ? 'green' : 'red', color: 'white', paddingInline: '10px', borderRadius: '25px', width: 'fit-content' };

    if (state === 'Do') message = `Do: ${text}`;
    if (state === 'Dont') message = `Dont: ${text}`;

    return React.createElement(
        'div',
        {style: { marginTop:'10px'}},
        React.createElement(
            'div',
            { style: textStyle },
            state
        ),
        React.createElement(
            'div',
            { style: boxStyle },
            React.createElement('div', null, message),
            React.createElement('div', { style: { marginTop: '5px' } }, element)
        )
    );
};

import React from 'react';
import { useOf } from '@storybook/blocks';

interface StateProps {
    of?: any;
    state: string;
    text?: string;
}

export const State = ({ of, state, text }: StateProps) => {

    const resolvedOf = useOf(of || 'story', ['story', 'meta']);

    let message:string = '';
    let boxStyle:React.CSSProperties = {};

    switch (resolvedOf.type) {
        case 'story':
            message = resolvedOf.story.name;
            break;
        case 'meta':
            message = resolvedOf.preparedMeta.title;
            break;
        default:
            return '';
    }


    const styles:{[key:string]:React.CSSProperties} = {
    warning: { border: '1px solid red', backgroundColor: '#ffe6e6', color: 'red' },
    hint: { border: '1px solid blue', backgroundColor: '#e6f0ff', color: 'blue' },
    success: { border: '1px solid green', backgroundColor: '#e6ffe6', color: 'green' }
    };

    boxStyle = { ...styles[state], padding: '10px', borderRadius: '5px', marginTop: '10px' };


    if (state === 'hint') message = `Hint: ${message}`;
    if (state === 'success') message = `Success: ${message}`;
    if (state === 'warning') message = `Warning: ${message}`;

    if (text) message = `${message} - ${text}`

    return React.createElement('div', { style: boxStyle }, message);
};

import React from 'react';

interface StoryBoxProps {
    element: any;
    text?: string;
}

export const StoryBox = ({ element, text }:StoryBoxProps) => {

    const boxStyle = {
        border: '1px solid #ccc',
        backgroundColor: '#f9f9f9',
        padding: '10px',
        borderRadius: '5px',
        marginTop: '10px'
    };

    return React.createElement(
        'div',
        { style: boxStyle },
        text && React.createElement('div', { style: { marginBottom: '10px' } }, text),
        React.createElement('div', null, element)
    );
};

import React from 'react';

interface TabsProps {
    tabs: { name: string, content: any }[];
}

export const Tabs = ({ tabs }: TabsProps) => {
    const [selectedTab, setSelectedTab] = React.useState(tabs[0].name);

    const tabStyle = (isSelected: boolean) => ({
        padding: '10px',
        border: 'none',
        backgroundColor: isSelected ? '#dddddd' : 'transparent',
        cursor: 'pointer'
    });

    const containerStyle = {
        display: 'flex',
        marginBottom: '10px'
    };

    return React.createElement(
        'div',
        null,
        React.createElement(
            'div',
            { style: containerStyle },
            tabs.map(tab => React.createElement(
                'div',
                {
                    key: tab.name,
                    style: tabStyle(selectedTab === tab.name),
                    onClick: () => setSelectedTab(tab.name)
                },
                tab.name
            ))
        ),
        tabs.find(tab => tab.name === selectedTab)?.content
    );
};

